        learn: ['<code>banner login</code> girişten önce, <code>banner motd</code> sonra; ayraçla başlar/biter.', 'admin parolası: <code>username admin password … role sysadmin</code>.', 'running = RAM, startup = startup.xml.', 'Kanıt: write memory → reload → kontrol.'],
